package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Last write step: only a change that went through is recorded. */
public class RecordClaimAdded {
    public void record(@RequestParam(name = "by", required = false) String by,
            @Val Claim claim, PersonRepository people, Audit audit) {
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        audit.record("CLAIM_ADDED sheet=" + claim.getSheetId() + " by=" + (by == null ? "" : by)
                + " person=" + (person == null ? "" : person.getName())
                + " amount=" + claim.getAmount() + " date=" + claim.getDate() + claim.getAuditRef() + claim.getAuditTags());
        if (claim.isLateEntry()) {
            audit.record("LATE_ENTRY sheet=" + claim.getSheetId() + " by=" + (by == null ? "" : by)
                    + " person=" + (person == null ? "" : person.getName())
                    + " amount=" + claim.getAmount() + " date=" + claim.getDate());
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadClaim {
    public void load(@PathVariable("sheetId") String sheetId,
            @PathVariable("claimId") long claimId, ClaimRepository claims,
            Out<Claim> claim) throws ClaimNotFoundException {
        Claim found = claims.find(sheetId.trim(), claimId);
        if (found == null) {
            throw new ClaimNotFoundException(claimId);
        }
        claim.set(found);
    }
}
